const applyOutcomeChange = Effect.fn('RecordPaymentReconciliationDecisionAction.applyOutcomeChange')(
  function* applyOutcomeChange(
    context: DecisionContext,
    current: Option.Option<PaymentAggregateRecord>,
    step: AppliedStep,
    decisionId: string,
    provenance: PaymentExecutionProvenance,
  ) {
    if (Option.isNone(step.change)) {
      return Option.none<AppliedOutcome>();
    }
    const change = step.change.value;
    const before = yield* Effect.fromOption(findOperation(current, change.operationId)).pipe(
      Effect.catchTag('NoSuchElementError', () =>
        Effect.fail(
          paymentEvidenceRejected(
            'payment_reconciliation_decision_not_applicable',
            'The operation is not in this Payment',
          ),
        ),
      ),
    );
    const { aggregate } = context.services;
    const transitioned = yield* aggregate.transitionOperationOutcome({
      causedBy: { kind: 'RECONCILIATION', sourceId: decisionId },
      expectedOutcomeRevision: change.expectedOutcomeRevision,
      operationId: change.operationId,
      paymentId: before.paymentId,
      provenance,
      to: change.to,
    });
    const payment = yield* aggregate.lockPayment(before.paymentId);
    const applied: AppliedOutcome = { before, coverageRevision: payment.coverageRevision, record: transitioned.record };
    yield* emitOutcomeChanged(context, applied, decisionId, provenance);
    return Option.some(applied);
  },
);

/**
 * Records one governed reconciliation decision (#1151) under the Payment row lock and the case row lock.
 * The decision row is appended first; any outcome change cites it as its RECONCILIATION cause, so the
 * audit trail explains every change. Closing a case advances the coverage revision so no proof issued
 * before the hold can silently become Current again.
 */
export const handleRecordPaymentReconciliationDecision = Effect.fn('RecordPaymentReconciliationDecisionAction.handle')(
  function* handleRecordPaymentReconciliationDecision(
    payload: RecordPaymentReconciliationDecisionPayload,
    context: DecisionContext,
  ) {
    const { aggregate, evidence } = context.services;
    const provenance = provenanceOf(context);
    const { current, locked } = yield* lockSubject(context, payload.caseId);
    // One transaction connection: the evidence reads run in order.
    const [facts, caseEvidence] = yield* Effect.all(
      [evidenceFactsFor(context, payload.decision), caseEvidenceFor(context, payload.decision, locked, current)],
      { concurrency: 1 },
    );
    const step = yield* requireApplied(
      decidePaymentReconciliation({
        body: payload.decision,
        caseEvidence,
        evidence: facts,
        operations: operationViews(current),
        subject: { operationId: locked.operationId, paymentId: locked.paymentId, status: locked.status },
      }),
    );
    const countedElsewhere = yield* attachedEffectCountedElsewhere(
      context,
      current,
      step,
      facts,
      locked.operationId ?? Option.getOrUndefined(attachedOperationId(payload.decision)),
      provenance,
    );
    if (countedElsewhere) {
      return yield* paymentEvidenceRejected(
        'payment_reconciliation_evidence_not_qualified',
        'The economic effect already counts toward another Payment operation',
      );
    }
    const returnCountedElsewhere = yield* closedReturnCountedElsewhere(
      context,
      current,
      step,
      closingCaseObservationId(payload.decision, locked),
      provenance,
    );
    if (returnCountedElsewhere) {
      return yield* paymentEvidenceRejected(
        'payment_reconciliation_obligation_unresolved',
        'The held return already counts for another Payment',
      );
    }
    const decidedAt = yield* DateTime.now;
    const decision = yield* evidence.insertDecision({
      caseId: locked.caseId,
      decidedAt,
      decisionKind: step.decisionKind,
      evidenceRef: step.evidenceRef,
      operationId: Option.orElse(attachedOperationId(payload.decision), () =>
        Option.fromUndefinedOr(locked.operationId),
      ),
      provenance,
      reason: payload.reason,
      resultingOutcome: step.resultingOutcome,
    });
    const applied = yield* applyOutcomeChange(context, current, step, decision.decisionId, provenance);
    const settled = step.closeCase
      ? yield* evidence.closeCase({ caseId: locked.caseId, closedAt: decidedAt, expectedRevision: locked.revision })
      : locked;
    if (step.closeCase && locked.paymentId !== undefined) {
      yield* aggregate.bumpCoverageRevision(locked.paymentId);
    }
    const result: RecordPaymentReconciliationDecisionResult = {
      caseId: settled.caseId,
      caseKind: settled.caseKind,
      caseRevision: settled.revision,
      caseStatus: settled.status,
      decision: {
        actionInvocationId: decision.provenance.actionInvocationId,
        caseId: decision.caseId,
        compositionRevision: decision.provenance.compositionRevision,
        decidedAt: decision.decidedAt,
        decisionId: decision.decisionId,
        decisionKind: decision.decisionKind,
        evidenceRef: Option.fromNullishOr(decision.evidenceRef),
        reason: decision.reason,
        resultingOutcome: Option.fromNullishOr(decision.resultingOutcome),
      },
      outcomeChange: applied.pipe(
        Option.map(({ before, record }) => ({
          fromOutcome: before.outcome,
          operationId: record.operationId,
          outcomeRevision: record.outcomeRevision,
          toOutcome: record.outcome,
        })),
      ),
      paymentId: Option.fromNullishOr(locked.paymentId),
    };
    return result;
  },
);

